int archive_read_support_zip_cleanup(struct archive_read *a) {
  struct zip *zip = (struct zip *)a->format->data;

  if (zip->zlib_data != NULL) {
    inflateEnd(&zip->z_stream);
    free(zip->zlib_data);
    zip->zlib_data = NULL;
  }

  if (zip->bz2_data != NULL) {
    BZ2_bzDecompressEnd(&zip->bz2_stream);
    free(zip->bz2_data);
    zip->bz2_data = NULL;
  }

  if (zip->lzma_data != NULL) {
    lzma_stream_decoder_end(&zip->lzma_stream);
    free(zip->lzma_data);
    zip->lzma_data = NULL;
  }

  struct zip_entry *entry, *entry_next;
  for (entry = zip->entries; entry != NULL; entry = entry_next) {
    entry_next = entry->next;
    free(entry->filename);
    free(entry);
  }

  free(zip);
  a->format->data = NULL;
  return ARCHIVE_OK;
}

int archive_read_support_zip_cleanup(struct archive_read *a) {
    struct zip *zip = (struct zip *)a->format->data;

    if (zip->z_stream != NULL)
        free(zip->z_stream);
    if (zip->bz_stream != NULL)
        free(zip->bz_stream);
    if (zip->lzma_stream != NULL)
        free(zip->lzma_stream);

    struct zip_entry *entry = zip->entries;
    struct zip_entry *next;
    while (entry != NULL) {
        next = entry->next;
        free(entry->filename);
        free(entry->extra);
        free(entry);
        entry = next;
    }

    free(zip);
    a->format->data = NULL;
    return ARCHIVE_OK;
}

int
archive_read_support_zip_cleanup(struct archive_read *a)
{
  struct zip *zip = (struct zip *)(a->format->data);

  if (zip->zlib != NULL) {
    inflateEnd(zip->zlib);
    free(zip->zlib);
    zip->zlib = NULL;
  }

  if (zip->lzma != NULL) {
    lzma_end(zip->lzma);
    free(zip->lzma);
    zip->lzma = NULL;
  }

  if (zip->bz2 != NULL) {
    BZ2_bzDecompressEnd(zip->bz2);
    free(zip->bz2);
    zip->bz2 = NULL;
  }

  while (zip->entries != NULL) {
    struct zip_entry *entry = zip->entries;
    zip->entries = entry->next;

    if (entry->local_file_name != NULL)
      free(entry->local_file_name);

    if (entry->extra_field != NULL)
      free(entry->extra_field);

    free(entry);
  }

  if (zip->central_dir != NULL)
    free(zip->central_dir);

  if (zip->local_dir != NULL)
    free(zip->local_dir);

  free(zip);
  a->format->data = NULL;

  return (ARCHIVE_OK);
}

int archive_read_free_zip(struct archive_read *a) {
  struct zip *zip = (struct zip *)(a->format_data);

  if (zip == NULL)
    return (ARCHIVE_OK);

  if (zip->zstrm.zalloc)
    inflateEnd(&zip->zstrm);
  if (zip->bzstream)
    BZ2_bzDecompressEnd(zip->bzstream);
  if (zip->lzma_stream)
    lzma_end(zip->lzma_stream);

  while (zip->entries) {
    struct zip_entry *entry = zip->entries;
    zip->entries = entry->next;
    free(entry->filename);
    free(entry);
  }

  free(zip->central_directory);
  free(zip);
  a->format_data = NULL;

  return (ARCHIVE_OK);
}

int zip_cleanup(struct archive_read *a) {
    struct zip *zip = (struct zip *)a->format->data;

    if (zip == NULL)
        return ARCHIVE_OK;

    if (zip->zstrm != NULL)
        free(zip->zstrm);
    if (zip->lzma != NULL)
        lzma_free(zip->lzma);
    if (zip->bz_stream != NULL)
        BZ2_bzDecompressEnd(zip->bz_stream);
    if (zip->window != NULL)
        free(zip->window);

    while (zip->entries != NULL) {
        struct zip_entry *entry = zip->entries;
        zip->entries = entry->next;
        if (entry->filename != NULL)
            free(entry->filename);
        free(entry);
    }

    if (zip->central_dir != NULL)
        free(zip->central_dir);

    free(zip);
    a->format->data = NULL;

    return ARCHIVE_OK;
}
